@@ -0,0 +1,95 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria the customer list is narrowed by. Both parts are applied by
+ * {@link CustomerRepository}, so the UI never has to hold more than one page.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ *
+ * <ul>
+ * <li><b>name</b> — the text is split on whitespace into terms, and every term
+ * must occur as a substring of the first name or of the last name. Case and
+ * accents are ignored on both sides, so {@code makinen} finds {@code Mäkinen}
+ * and vice versa. An empty name matches everything.
+ * <li><b>statuses</b> — an empty set matches every status; otherwise the
+ * customer's status must be one of the selected ones.
+ * </ul>
+ *
+ * @param name     the raw name filter, leading and trailing whitespace removed
+ * @param statuses the statuses to show, empty for all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        EnumSet<CustomerStatus> copy = EnumSet.noneOf(CustomerStatus.class);
+        if (statuses != null) {
+            copy.addAll(statuses);
+        }
+        statuses = Collections.unmodifiableSet(copy);
+    }
+
+    /** A filter on the name alone. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** {@code true} when this filter excludes nothing. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * The statuses in {@link CustomerStatus} declaration order, which is the
+     * order they appear in as a URL parameter.
+     */
+    public List<CustomerStatus> statusesInDeclarationOrder() {
+        return Arrays.stream(CustomerStatus.values()).filter(statuses::contains).toList();
+    }
+
+    /**
+     * Compiles this filter into a predicate. The terms are normalised once, not
+     * once per customer, so the repository can run it over a whole table.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = WHITESPACE.splitAsStream(name)
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toList();
+        Set<CustomerStatus> selected = statuses;
+        return customer -> {
+            if (!selected.isEmpty() && !selected.contains(customer.status())) {
+                return false;
+            }
+            if (terms.isEmpty()) {
+                return true;
+            }
+            // A term may match the first name or the last name, but never span
+            // the two, so they are joined by a character no term can contain.
+            String searchable = fold(customer.firstName()) + '\n' + fold(customer.lastName());
+            return terms.stream().allMatch(searchable::contains);
+        };
+    }
+
+    /** Lower-cases and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
