+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** What {@link CustomerFilter} does and does not match. */
+class CustomerFilterTest {
+
+    private static final Customer ADA = customer("Ada", "Aaltonen", CustomerStatus.ACTIVE);
+    private static final Customer JARNO = customer("Jarno", "Mäkinen", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = customer("Joséphine", "Engberg", CustomerStatus.CLOSED);
+
+    private static Customer customer(String firstName, String lastName, CustomerStatus status) {
+        return new Customer(1, firstName, lastName, "e@example.com", "Finland", status);
+    }
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    @Test
+    void emptyFilterMatchesEverything() {
+        assertTrue(matches(CustomerFilter.EMPTY, ADA));
+        assertTrue(matches(CustomerFilter.EMPTY, JARNO));
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(CustomerFilter.byName("   ").isEmpty(), "Whitespace alone is not a filter");
+    }
+
+    @Test
+    void everyTermMustMatch_inEitherOrder() {
+        assertTrue(matches(CustomerFilter.byName("ada aal"), ADA));
+        assertTrue(matches(CustomerFilter.byName("aal ada"), ADA));
+        assertTrue(matches(CustomerFilter.byName("  ada   aal  "), ADA));
+        assertFalse(matches(CustomerFilter.byName("ada virtanen"), ADA));
+    }
+
+    @Test
+    void aTermMayNotSpanFirstAndLastName() {
+        assertFalse(matches(CustomerFilter.byName("adaaaltonen"), ADA));
+        assertFalse(matches(CustomerFilter.byName("a aaltonena"), ADA));
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredBothWays() {
+        for (String term : List.of("makinen", "MAKINEN", "mäkinen", "MÄKINEN", "Mäk")) {
+            assertTrue(matches(CustomerFilter.byName(term), JARNO), term + " must find Mäkinen");
+        }
+        assertTrue(matches(CustomerFilter.byName("josephine"), JOSEPHINE));
+        assertTrue(matches(CustomerFilter.byName("joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void statusesNarrowAndAnEmptySetDoesNot() {
+        CustomerFilter activeOrClosed =
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertTrue(matches(activeOrClosed, ADA));
+        assertFalse(matches(activeOrClosed, JARNO));
+        assertTrue(matches(activeOrClosed, JOSEPHINE));
+
+        assertTrue(matches(new CustomerFilter("", Set.of()), JARNO));
+    }
+
+    @Test
+    void bothPartsMustHold() {
+        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.PENDING));
+        assertFalse(matches(filter, ADA), "Name matches but status does not");
+    }
+
+    @Test
+    void statusesComeOutInDeclarationOrder() {
+        CustomerFilter filter = new CustomerFilter("",
+                Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+        assertTrue(filter.statusesInDeclarationOrder()
+                .equals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+    }
+}
